class SyncJob
{
    // Breaking change 5: In EF 9, synchronous methods (ToList, SaveChanges) on Cosmos
    // now throw by default. Use async equivalents.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

// Breaking change 6: Raw SQL queries referencing "Discriminator" must be updated
// IF you choose to adopt the new "$type" property name. Since we preserved
// "Discriminator" above, existing queries like:
//   SELECT * FROM c WHERE c.Discriminator = 'Blog'
// continue to work unchanged.

